PG.configure('/festivals/krishna-janmashtami/',[('','Kṛṣṇa Janmāṣṭamī','Midnight in Mathurā')],'blue','Kṛṣṇa Janmāṣṭamī','Lord','Janmāṣṭamī')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/krishna-janmashtami/'
i=0
K=lambda: god('#2a5aa8')
KB=lambda: krishna_child()
VAS=lambda: god('#7a3fa0')
DEV=lambda: person('#c0392b')
KAMSA=lambda: demon('#7a1d12')
YAS=lambda: mother('#e0a800')
def footprints(n=5): return ''.join(f'<g transform="translate({k*22} {(-1)**k*6})"><ellipse rx="5" ry="8" fill="#fff"/>'+''.join(f'<circle cx="{-4+j*2}" cy="-11" r="1.4" fill="#fff"/>' for j in range(5))+'</g>' for k in range(n))
def basket_baby(): return '<path d="M-24 0 q24 14 48 0 l-4 -14 h-40z" fill="#c9a06a"/>'+g(0,-10,.6,baby())
def snake_hood(): return '<path d="M-30 0 q30 -70 60 0" fill="#2a6a3a"/>'+''.join(f'<circle cx="{-18+k*12}" cy="-30" r="5" fill="#3a8a4a"/>' for k in range(4))
def chakkuli(): return '<path d="M0 0 m-14 0 a14 14 0 1 0 28 0 a10 10 0 1 0 -20 0 a6 6 0 1 0 12 0" fill="none" stroke="#c98a3a" stroke-width="4"/>'
def pot_hang(): return '<path d="M0 -60 v26" stroke-width="2"/>'+pot('#c98a5a')
def flute(): return '<path d="M-30 0 l60 -20" stroke="#6a4a2a" stroke-width="5"/>'+''.join(f'<circle cx="{-16+k*10}" cy="{5-k*3.4:.1f}" r="1.5" fill="#111"/>' for k in range(4))
def tiger_man(): return person('#ffb000')+''.join(f'<path d="M-10 -{8+k*7} h20" stroke="#111" stroke-width="2"/>' for k in range(4))
COV=covart('A cradle with baby Kṛṣṇa under a moonlit sky, little white footprints leading to it, a pot of butter and a flute',f'<rect width="440" height="196" fill="#20243a"/>'+''.join(f'<circle cx="{(37*k)%440}" cy="{(23*k*k)%110+8}" r="1.4" fill="#fff8d0" stroke="none"/>' for k in range(1,20))+g(360,46,1.1,moonrise(0,0,20))+'<rect y="160" width="440" height="36" fill="#3a4a6a"/>'+g(260,186,1.7,cradle())+g(260,166,1.1,baby())+g(40,180,1,footprints(7))+g(120,190,1.2,pot('#fff8e7'))+g(380,180,1,flute()))
pp=[foreword(i,['At midnight on the eighth day of the dark fortnight, in a prison cell in Mathurā, <b>Kṛṣṇa</b> was born. The chains fell away, the guards slept, and his father carried him through a storm across the Yamunā to safety in Gokula. That midnight is <b>Janmāṣṭamī</b>, called <b>Gōkulāṣṭamī</b> in Karnataka.','Homes draw little white footprints from the door to the shrine, fast until moonrise or midnight, rock a cradle and fill the kitchen with <b>uṇḍe</b> and <b>cakkuli</b>. Udupi turns the next day into Viṭṭal Piṇḍi, with tiger dancers and pots of curd broken in the streets.','This article gives the Bhāgavata’s birth verse and the Gītā’s promise, tells the night of the birth scene by scene, the childhood in Gokula, and every custom, from Karnataka homes to Udupi, Mathurā and Mumbai’s human pyramids.'],[('z','Why midnight?'),('b','Because that’s when the Bhāgavata says he was born, Zappy: at midnight, in deep darkness, like the moon rising in the east.')]),
 glance([('Name','Kṛṣṇa Janmāṣṭamī; Gōkulāṣṭamī, Śrī Jayantī (Karnataka); Janmāṣṭamī, Gokulaṣṭamī'),('When','Kṛṣṇa Aṣṭamī of Śrāvaṇa (amānta) / Bhādrapada (pūrṇimānta); August–September; at midnight, ideally with the Rohiṇī star'),('Birth','To Devakī and Vasudeva in Kaṃsa’s prison, Mathurā; raised by Yaśodā and Nanda in Gokula'),('Texts','Bhāgavata Purāṇa book 10 (birth 10.3); Harivaṃśa; Viṣṇu Purāṇa book 5'),('Customs','Fast, footprints, cradle at midnight, arghya to the moon, uṇḍe and cakkuli'),('Next day','Nandotsava; Udupi’s Viṭṭal Piṇḍi; Dahī Haṇḍī in Maharashtra'),('Karnataka','Udupi Kṛṣṇa Maṭha; mosaru kuḍike; huli-vēṣa')],svg(560,140,'A moonlit night with a cradle and a flute',f'<rect width="560" height="140" fill="#20243a"/>'+g(460,40,1,moonrise(0,0,18))+g(280,130,1.5,cradle())+g(280,112,1,baby())+g(140,120,1,flute()))),
 reading('date','THE EIGHTH DAY AT MIDNIGHT','Aṣṭamī, Rohiṇī and two dates',svg(560,160,'The waning half-moon of the eighth night with the Rohiṇī star beside it',f'<rect width="560" height="160" fill="#20243a"/>'+'<path d="M280 40 a40 40 0 0 1 0 80 z" fill="#fff8d0" stroke="none"/><circle cx="360" cy="60" r="6" fill="#ff8c1a" stroke="none"/>'+lab(360,90,'Rohiṇī').replace('#111','#fff8d0')+lab(280,145,'Kṛṣṇa Aṣṭamī: half moon, waning').replace('#111','#fff8d0')),['<b>The day.</b> Kṛṣṇa was born on the eighth lunar day (<b>aṣṭamī</b>) of the dark fortnight. In the amānta calendar of Karnataka this is in <b>Śrāvaṇa</b>; in the pūrṇimānta calendar of the north the same night is in Bhādrapada.','<b>The hour.</b> At midnight (<i>niśītha</i>), with the moon, by tradition, in the nakṣatra <b>Rohiṇī</b>. When aṣṭamī and Rohiṇī coincide at midnight the day is called <b>Jayantī</b>, specially auspicious.','<b>Two dates.</b> Families often keep Janmāṣṭamī on different days: some follow the aṣṭamī at midnight (often called the Smārta reckoning), others insist on Rohiṇī or the aṣṭamī at sunrise (many Vaiṣṇava and Mādhva traditions, including Udupi). Ask your family priest.','<b>The moon.</b> The half-moon rises around midnight on aṣṭamī: hence the Bhāgavata’s image of Kṛṣṇa appearing like the moon in the east, and the arghya to the moon in Karnataka homes.'],[('z','Why does Udupi sometimes celebrate on another day?'),('b','It follows its own almanac rules, Zappy, by the moon and Rohiṇī. Both days are kept with full love.')],'Born at <b>midnight on the eighth</b>.'),
 story('prophecy','THE VOICE IN THE SKY','Kaṃsa and Devakī',strip('Three panels: Kaṃsa driving his sister Devakī’s wedding chariot; a voice from the sky warning him; Devakī and Vasudeva in chains in prison',[panel([(KAMSA(),.9),(DEV(),.8),(VAS(),.8)],'#fde4e4',150),panel([(KAMSA(),1),('<path d="M-40 -100 q40 -30 80 0" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="4 3"/>',1)],'#e9e3f5',150),panel([(DEV(),.9),(VAS(),.9),('<path d="M-30 -30 h60 M-30 -10 h60" stroke="#666" stroke-width="3"/>',1)],'#3a3a4a',150)],['the wedding','the prophecy','the prison']),'Bhāgavata Purāṇa 10.1–2.',['<b>Kaṃsa</b>, the tyrant of Mathurā, loved his cousin-sister <b>Devakī</b>, and on her wedding day to <b>Vasudeva</b> he himself drove their chariot.','A voice from the sky rang out: “Fool! The eighth child of the woman you are driving will kill you.” Kaṃsa drew his sword to kill Devakī there and then.','Vasudeva calmed him with a promise: he would hand over every child Devakī bore. Kaṃsa let her live, but threw them both into prison.','One by one Kaṃsa killed six of their babies. The seventh, <b>Balarāma</b>, was transferred by Viṣṇu’s power, Yogamāyā, from Devakī’s womb to Rohiṇī’s in Gokula; people were told Devakī had miscarried.','Then Devakī conceived the eighth child. Kaṃsa doubled the guards and waited.'],[('z','Why didn’t Kaṃsa just keep them apart?'),('b','Fear makes poor plans, Zappy. The whole story is about a tyrant who can’t stop what he fears.')],'A tyrant <b>waits in fear</b>.'),
 verse('v-birth','Bhāgavata 10.3.8','The birth at midnight',['niśīthe tama udbhūte jāyamāne janārdane','devakyāṃ devarūpiṇyāṃ viṣṇuḥ sarvaguhāśayaḥ','āvirāsīd yathā prācyāṃ diśīndur iva puṣkalaḥ'],svg(200,150,'A full moon rising in the east over a dark prison wall',f'<rect width="200" height="150" fill="#20243a"/>'+g(150,50,1.2,moonrise(0,0,24))+'<rect y="100" width="200" height="50" fill="#5a5a6a"/>'+''.join(f'<path d="M{x} 100 v50" stroke="#3a3a4a" stroke-width="4"/>' for x in range(20,200,30))),'At midnight, when deep darkness had arisen, as Janārdana was being born, Viṣṇu, who dwells in the heart of all, appeared in the divine Devakī, as the full moon rises in the eastern sky.',[('niśīthe','at midnight'),('tama udbhūte','when darkness had arisen'),('sarva-guhāśayaḥ','dwelling in every heart'),('āvirāsīt','appeared'),('prācyāṃ diśi','in the eastern quarter'),('induḥ puṣkalaḥ','the full moon')],'<b>The moon in the east.</b> Śuka compares the birth to the full moon rising: darkness all around, then light from the east. Devakī is the eastern sky, Kṛṣṇa the moon. The next verses describe the child with four arms, holding conch, discus, mace and lotus, who then becomes an ordinary baby at his parents’ request.',k='<b>Light rises</b> in the darkest hour.',note='Text: Bhāgavata Purāṇa 10.3.8 as on wisdomlib.org (Sanskrit), set in IAST.'),
 story('yamuna','ACROSS THE YAMUNĀ','The night journey to Gokula',strip('Three panels: Vasudeva in prison with the chains falling away; carrying the baby in a basket across the flooded Yamunā, the serpent Śeṣa sheltering them; exchanging the baby with Yaśodā’s daughter',[panel([(VAS(),.9),(DEV(),.8),(baby(),.6)],'#3a3a4a',150),panel([(river(144,120,'#3a5a8a'),1),(VAS(),.7),(snake_hood(),.6)],'#20243a',None),panel([(YAS(),.8),(baby(),.6),(VAS(),.8)],'#fff3cf',150)],['the chains fall','through the storm','the exchange']),'Bhāgavata Purāṇa 10.3.',['At the child’s instruction, Vasudeva picked him up. The chains fell from his feet, the guards fell into deep sleep, and the prison doors swung open by themselves.','It was pouring with rain. Vasudeva carried the baby out in a basket on his head, and the serpent <b>Śeṣa</b> followed, spreading his hoods as an umbrella.','The <b>Yamunā</b> was in flood, but she parted to let them through, as the sea had parted for Rāma.','In Gokula, in the house of the cowherd chief <b>Nanda</b>, his wife <b>Yaśodā</b> had just given birth to a daughter, and lay asleep. Vasudeva laid Kṛṣṇa beside her, took the baby girl, and returned to the prison.','The doors closed, the chains returned. When Kaṃsa came to kill the eighth child, the girl slipped from his hands and rose into the sky as the goddess <b>Yogamāyā</b>, saying: the one who will kill you is born elsewhere.'],[('z','The goddess was the baby girl?'),('b','Yogamāyā herself, Zappy. Many Devī temples remember her as the sister of Kṛṣṇa.')],'Chains fall, <b>the river parts</b>.'),
 story('gokula','THE BUTTER THIEF','Childhood in Gokula',strip('Three panels: little Kṛṣṇa and friends climbing to a pot of butter hanging high; Yaśodā looking into his open mouth and seeing the universe; Yaśodā tying him to a mortar with a rope',[panel([(KB(),.9),(child(),.8),(pot_hang(),1)],'#fff3cf',150),panel([(YAS(),.8),(KB(),.7),('<circle r="18" fill="#20243a"/>'+''.join(f'<circle cx="{(-1)**k*k*2}" cy="{-k*2}" r="1.2" fill="#fff" stroke="none"/>' for k in range(8)),1)],'#e9e3f5',150),panel([(YAS(),.8),(KB(),.7),(mortar(),.8)],'#e3f5e9',150)],['the high pot','the universe inside','Dāmodara']),'Bhāgavata Purāṇa 10.7–10.',['In Gokula, Kṛṣṇa grew up among cowherds as Yaśodā’s darling, and the terror of every milkmaid’s pantry. With his friends he climbed on mortars and each other’s shoulders to reach the butter pots hung high from the ceiling.','When the boys complained he had eaten mud, Yaśodā made him open his mouth, and saw inside it the whole universe: earth, stars, Gokula, herself. Then she forgot, and loved him as her child again.','Once, angry at broken pots, she tied him to a heavy mortar with a rope; every rope was two fingers too short until he let himself be tied: hence <b>Dāmodara</b>, “rope round the belly” (read our '+L('/festivals/kartika/damodarashtakam/','Dāmodarāṣṭakam')+').','He killed the demoness Pūtanā, lifted Govardhana hill to shelter Gokula from Indra’s rain, danced on the serpent Kāliya and played the flute that drew the gopīs to the Rāsa.','Kaṃsa’s demons came one after another; all failed. At last Kṛṣṇa went to Mathurā and ended Kaṃsa, freeing his parents.'],[('z','God stole butter?'),('b','Only from those who loved him, Zappy. The stealing is a game of love; that’s why Udupi breaks curd pots for him.')],'The Lord as <b>a naughty child</b>.'),
 verse('v-gita','Bhagavad Gītā 4.7–8','Why he comes',['yadā yadā hi dharmasya glānir bhavati bhārata','abhyutthānam adharmasya tadātmānaṃ sṛjāmy aham','paritrāṇāya sādhūnāṃ vināśāya ca duṣkṛtām','dharmasaṃsthāpanārthāya sambhavāmi yuge yuge'],svg(200,150,'Kṛṣṇa as charioteer with a raised hand',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,140,1.2,K())+g(140,100,.7,conch())+g(60,100,.7,discus())),'Whenever dharma declines, O Bhārata, and adharma rises, then I send myself forth. To protect the good, to destroy evil-doers, to establish dharma, I come into being age after age.',[('glāniḥ','decline'),('abhyutthānam','rise'),('sṛjāmi','I send forth'),('paritrāṇāya','for protecting'),('dharma-saṃsthāpana','establishing dharma'),('yuge yuge','in age after age')],'<b>The reason for the birthday.</b> Kṛṣṇa himself gives the theology of Janmāṣṭamī to Arjuna: God is born whenever goodness is in danger. The prison birth is the picture of it: the tyrant at the height of his power, the child born in his jail.',k='He comes <b>age after age</b>.',note='Text: Bhagavad Gītā 4.7–8, BBT edition (prabhupadabooks.com), set in IAST.'),
 reading('home','GŌKULĀṢṬAMĪ AT HOME','Footprints, fasting and the cradle',svg(560,160,'Little white footprints leading from a door to a shrine where a cradle hangs',f'<rect width="560" height="160" fill="#e3eaf3"/>'+'<rect x="20" y="20" width="60" height="140" fill="#8a5a3a"/>'+'<rect y="140" width="560" height="20" fill="#c9a06a"/>'+g(110,148,1.1,footprints(10))+g(470,150,1.4,cradle())+g(470,132,.9,baby())),['<b>Little feet.</b> With rice-flour paste, the women of the house draw tiny footprints from the front door to the shrine, as if baby Kṛṣṇa had walked in. Children love to make them.','<b>The fast.</b> Many fast through the day, some without water, until the moon rises or midnight, when the birth is celebrated and the fast broken with the offered food.','<b>Midnight.</b> An image of baby Kṛṣṇa, bathed in milk and decked in new clothes, is laid in a decorated cradle and rocked while lullabies and Haridāsa songs are sung; conches and bells announce the birth.','<b>Kṛṣṇārghya.</b> At moonrise many Karnataka families offer water (arghya) to the moon, with a verse, honouring Kṛṣṇa of the lunar dynasty. Children dress as Kṛṣṇa and Rādhā, flute and peacock feather included.'],[('z','Why footprints?'),('b','So little Kṛṣṇa walks into the house, Zappy. Every home wants him to visit.')],'Footprints <b>for a small visitor</b>.'),
 cards('food','UṆḌE AND CAKKULI','The snack festival',fig_row('Cakkuli spirals, laddus, a pot of butter and a bowl of beaten rice',[(chakkuli(),1.6),(laddu(),1.8),(pot('#fff8e7'),1.4),(plate(),1.6)],['cakkuli','uṇḍe','beṇṇe','avalakki'],gy=150),[('🌀','Cakkuli and kōḍubaḷe','Crunchy spirals and rings of rice flour, pressed and fried, the signature of Karnataka’s Gōkulāṣṭamī.'),('🟡','Uṇḍe','Laddus of every kind: rave (semolina), besan, sesame, coconut, and the special <b>tambiṭṭu</b> in some homes.'),('🧈','Butter and curd','Fresh butter, curd and milk sweets: the butter thief’s favourites, offered first.'),('🍚','Avalakki','Beaten rice, recalling Sudāmā (Kucēla), who brought Kṛṣṇa a handful of it as his only gift and was made rich.')],[('z','So many snacks!'),('b','A plate goes to every neighbour, Zappy. Janmāṣṭamī is shared by the kitchen.')],'A kitchen <b>full of crunch</b>.'),
 reading('udupi','UDUPI: VIṬṬAL PIṆḌI','Karnataka’s great Kṛṣṇa festival',svg(560,170,'A temple street with a pot of curd hung high, young men climbing, and a tiger-painted dancer',f'<rect width="560" height="170" fill="#e3eaf3"/>'+'<rect y="140" width="560" height="30" fill="#c9a06a"/>'+'<path d="M180 20 v120 M380 20 v120 M180 30 h200" stroke="#6a4a2a" stroke-width="6"/>'+g(280,60,1,pot_hang())+g(260,140,.9,person('#2a5aa8'))+g(300,140,.9,person('#c0392b'))+g(470,140,1.1,tiger_man())+g(90,140,.8,palace())),['<b>The temple.</b> The Kṛṣṇa of <b>Udupi</b> was installed by <b>Madhvācārya</b> about eight centuries ago; devotees see him through the small window of nine holes (Kanakana kiṇḍi), where the poet-saint Kanaka Dāsa is said to have had darśan.','<b>Midnight.</b> At the birth hour the temple offers arghya and worship; the eight Mādhva maṭhas take part under the presiding swāmi of the Paryāya.','<b>Viṭṭal Piṇḍi.</b> The next day is the <b>Śrī Kṛṣṇa Līlotsava</b>: a clay image of Kṛṣṇa is carried in procession with the festival images round the car street and finally immersed in the Madhva Sarovara.','<b>Mosaru kuḍike and huli-vēṣa.</b> Pots of curd and coloured water hung high across the street are broken by young men dressed as gopālas, re-enacting the butter raids; dancers painted as tigers (<b>huli-vēṣa</b>, Tuḷu pili-vēṣa) leap through the crowds to drums.'],[('z','Tigers at a Kṛṣṇa festival?'),('b','Udupi’s pili-vēṣa, Zappy. Painted from head to tail. It’s their festival as much as anyone’s.')],'Curd pots, tigers and <b>a clay Kṛṣṇa</b>.'),
 verse('v-madhura','Madhurāṣṭakam, verse 1','Everything about him is sweet',['adharaṃ madhuraṃ vadanaṃ madhuraṃ','nayanaṃ madhuraṃ hasitaṃ madhuram','hṛdayaṃ madhuraṃ gamanaṃ madhuraṃ','madhurādhipater akhilaṃ madhuram'],svg(200,150,'Kṛṣṇa playing the flute with a peacock feather',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,140,1.2,K())+g(130,92,.8,flute())+'<path d="M100 26 q8 -14 0 -22 q-8 8 0 22z" fill="#2a9d6f"/>'),'His lips are sweet, his face is sweet, his eyes are sweet, his smile is sweet, his heart is sweet, his walk is sweet: everything about the lord of sweetness is sweet.',[('adharam','lips'),('vadanam','face'),('nayanam','eyes'),('hasitam','smile'),('gamanam','walk, gait'),('akhilam','everything')],'<b>The child’s birthday song.</b> Vallabhācārya’s Madhurāṣṭakam is sung everywhere on Janmāṣṭamī night, often as the cradle is rocked. Its eight verses list every part of Kṛṣṇa and find each one sweet: the devotion of a mother looking at her baby.',k='<b>Everything</b> is sweet.',note='Text as on our '+L('/vishnu/madhurashtakam/','Madhurāṣṭakam')+' page.'),
 cards('india','JANMĀṢṬAMĪ ACROSS INDIA','Mathurā, Vṛndāvana, Mumbai and beyond',fig_row('A human pyramid reaching for a pot, a temple, a dancer and a flute',[('<g>'+g(-14,0,.6,person('#c0392b'))+g(14,0,.6,person('#2a5aa8'))+g(0,-30,.6,person('#2a9d6f'))+'</g>',1.4),(palace(),.8),(person('#7a3fa0'),1.2),(flute(),1.2)],['Dahī Haṇḍī','Mathurā','Rāsa-līlā','Vṛndāvana'],gy=150),[('🧗','Maharashtra','<b>Dahī Haṇḍī</b> on the next day (Gopāl Kālā): teams of Govindās build human pyramids, sometimes many tiers high, to break a curd pot hung above the street. Safety rules now apply.'),('🛕','Mathurā and Vṛndāvana','The birthplace temple stands where the prison is said to have been; Vṛndāvana’s temples, Bāṅke Bihārī above all, keep the night with kīrtana and the shout “Nanda ke ānanda bhayo!”'),('💃','Manipur and Assam','<b>Rāsa-līlā</b> dance-dramas; Manipur’s classical Rāsa is among India’s most refined dance traditions.'),('🌍','Everywhere','ISKCON temples worldwide hold midnight abhiṣeka and kīrtana; Guruvāyūr in Kerala keeps Aṣṭami Rohiṇi with appam and feasting.')],[('z','How high do the pyramids go?'),('b','Some towers have eight or nine tiers, Zappy. Helmets and harnesses are now required in many places.')],'The whole country <b>breaks the pot</b>.'),
 reading('meaning','WHAT JANMĀṢṬAMĪ MEANS','God born in a prison',svg(560,150,'A prison door opening onto a moonlit river',f'<rect width="560" height="150" fill="#20243a"/>'+'<rect x="80" y="20" width="160" height="130" fill="#5a5a6a"/>'+'<rect x="130" y="50" width="60" height="100" fill="#20243a"/>'+g(430,50,1,moonrise(0,0,20))+'<path d="M260 140 q120 -20 300 0" stroke="#3a5a8a" stroke-width="16" fill="none"/>'),['<b>Light in the prison.</b> Kṛṣṇa is born not in a palace but in a tyrant’s jail, to parents in chains. Many teachers read it: God comes to us where we are most bound, and the chains fall. (Interpretation.)','<b>The child.</b> Janmāṣṭamī lets devotees love God as a baby: to rock him, feed him, scold him. This is <i>vātsalya</i>, parental love, which Yaśodā embodies and the Bhāgavata praises above awe.','<b>Fearlessness.</b> Kaṃsa’s fear makes him a murderer; Vasudeva’s love makes him walk into a storm. The night sets fear against love.','<b>The teacher.</b> The same child becomes the teacher of the Gītā. Many families end the night by reading a chapter of it.'],[('z','If I could do one thing for Janmāṣṭamī?'),('b','Draw the little footprints to your door, Zappy, and share a plate of cakkuli with a neighbour.')],'Chains fall where <b>love walks in</b>.'),
 end(i,['<b>When.</b> Kṛṣṇa Aṣṭamī of Śrāvaṇa, at midnight, ideally with Rohiṇī.','<b>Story.</b> Kaṃsa’s fear, the prison birth, across the Yamunā, Yogamāyā.','<b>Verses.</b> Bhāgavata 10.3.8; Gītā 4.7–8; Madhurāṣṭakam.','<b>Home.</b> Footprints, fasting, cradle, arghya, uṇḍe and cakkuli.','<b>Karnataka.</b> Udupi’s Viṭṭal Piṇḍi, mosaru kuḍike and huli-vēṣa.'],'Previous: '+L('/festivals/varamahalakshmi/','Varamahālakṣmī Vrata')+'. Next: '+L('/festivals/deepavali/','Dīpāvali')+'.','Janmāṣṭamī: midnight in Mathurā'),
 sources([('Texts:','Bhāgavata Purāṇa book 10 (chs. 1–3 birth; 7–10 childhood); 10.3.8 as on wisdomlib.org; Bhagavad Gītā 4.7–8 (BBT edition). Madhurāṣṭakam from our own page.'),('Customs:','Wikipedia, “Krishna Janmashtami” (dates, fasting, footprints, cradle, Dahī Haṇḍī, Rāsa-līlā, Nandotsava, regional names); Udupi customs as summarised in our earlier guide and temple tradition.')],'the Smārta/Vaiṣṇava date rules (summarised; practice varies by family and maṭha); Kṛṣṇārghya details; Udupi Viṭṭal Piṇḍi procession details (temple practice may change); the Kanakana kiṇḍi story (tradition).','Bhāgavata numbering as in the cited editions.')]
build(i,'MIDNIGHT · THE PRISON · THE BUTTER THIEF',COV,'Footprints to the cradle','The <b>midnight</b> and its date, the whole <b>birth night</b> scene by scene, the childhood in Gokula, the <b>verses</b>, and how <b>Karnataka</b> keeps Gōkulāṣṭamī, from home to Udupi.','Kṛṣṇa Janmāṣṭamī explained: Kṛṣṇa Aṣṭamī and Rohiṇī at midnight, Kaṃsa and Devakī, Bhāgavata 10.3.8, the crossing of the Yamunā, the butter thief of Gokula, Gītā 4.7–8, footprints and cradle, uṇḍe and cakkuli, Udupi’s Viṭṭal Piṇḍi and Dahī Haṇḍī.',pp)
print('kj ok',len(pp)+2)
